query:
query findLooById($id: ID) {
  loo(id: $id) {
    ...LooFragment
    reports {
      id
    }
  }
}
fragment LooFragment on Loo {
  id
  createdAt
  updatedAt
  verifiedAt
  active
  location {
    lat
    lng
  }
  name
  openingTimes
  accessible
  men
  women
  allGender
  babyChange
  children
  urinalOnly
  radar
  automatic
  noPayment
  paymentDetails
  notes
  removalReason
  attended
  geohash
  area {
    name
    type
  }
}
